import { Facebook, Instagram } from "lucide-react";

export default function SocialFabs({
  instagramUrl = "https://www.instagram.com/beyond.blades.asd.foundation/",
  instagramHandle = "@beyond.blades.asd.foundation",
  facebookUrl = "https://www.facebook.com/p/Beyond-Blades-ASD-Foundation-61590975493821/",
  facebookHandle = "Beyond Blades ASD Foundation",
}) {
  return (
    <>
      {/* Facebook FAB */}
      <a
        href={facebookUrl}
        target="_blank"
        rel="noopener noreferrer"
        data-testid="facebook-fab"
        aria-label={`Follow ${facebookHandle} on Facebook`}
        className="group fixed bottom-36 right-6 z-40 flex max-w-[90vw] items-center gap-3 rounded-full border border-white/40 bg-white/50 py-3 pl-4 pr-8 shadow-xl shadow-blue-900/10 backdrop-blur-xl transition-all hover:-translate-y-1 hover:bg-white/70 hover:shadow-2xl"
      >
        <span className="flex h-10 w-10 items-center justify-center rounded-full bg-gradient-to-tr from-blue-700 to-sky-400 text-white shadow-md">
          <Facebook className="h-5 w-5" />
        </span>

        <span className="flex flex-col leading-tight">
          <span className="text-[10px] font-semibold uppercase tracking-[0.18em] text-slate-500">
            Follow us
          </span>

          <span className="text-sm font-semibold text-slate-900 transition-colors group-hover:text-blue-700">
            {facebookHandle}
          </span>
        </span>

        <span className="pointer-events-none absolute -right-1 -top-1 h-3 w-3 animate-pulse rounded-full bg-blue-500 ring-2 ring-white" />
      </a>

      {/* Instagram FAB */}
      <a
        href={instagramUrl}
        target="_blank"
        rel="noopener noreferrer"
        data-testid="instagram-fab"
        aria-label={`Follow ${instagramHandle} on Instagram`}
        className="group fixed bottom-16 right-6 z-40 flex max-w-[90vw] items-center gap-3 rounded-full border border-white/40 bg-white/50 py-3 pl-4 pr-8 shadow-xl shadow-blue-900/10 backdrop-blur-xl transition-all hover:-translate-y-1 hover:bg-white/70 hover:shadow-2xl"
      >
        <span className="flex h-10 w-10 items-center justify-center rounded-full bg-gradient-to-tr from-pink-500 via-rose-500 to-amber-400 text-white shadow-md">
          <Instagram className="h-5 w-5" />
        </span>

        <span className="flex flex-col leading-tight">
          <span className="text-[10px] font-semibold uppercase tracking-[0.18em] text-slate-500">
            Follow us
          </span>

          <span className="text-sm font-semibold text-slate-900 transition-colors group-hover:text-blue-700">
            {instagramHandle}
          </span>
        </span>

        <span className="pointer-events-none absolute -right-1 -top-1 h-3 w-3 animate-pulse rounded-full bg-blue-500 ring-2 ring-white" />
      </a>
    </>
  );
}