export function parseEventDate(ymd) {
  const [y, m, d] = ymd.split("-").map(Number);
  return new Date(y, m - 1, d);
}

export function expandEvents(list) {
  const out = [];
  for (const e of list) {
    if (Array.isArray(e.dates) && e.dates.length > 0) {
      for (const d of e.dates) out.push({ ...e, date: d });
    } else if (e.date) {
      out.push(e);
    }
  }
  return out;
}