import { useEffect, useState } from "react";
import { Link } from "react-router-dom";

import {
  CheckCircle2,
  Loader2,
  Heart,
  AlertCircle,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { api } from "@/lib/api";

export default function DonateSuccessPage() {
  const [status, setStatus] =
    useState("loading");

  const [donation, setDonation] =
    useState(null);

  useEffect(() => {
    const hash = window.location.hash;

    const queryString =
      hash.includes("?")
        ? hash.split("?")[1]
        : "";

    const params =
      new URLSearchParams(
        queryString
      );

    const sessionId =
      params.get("session_id");

    if (!sessionId) {
      setStatus("error");
      return;
    }

    let cancelled = false;

    const checkStatus = async () => {
      try {
        const { data } =
          await api.get(
            `/donations/status/${sessionId}`
          );

        if (cancelled) return;

        setDonation(data);

        if (
          data.payment_status ===
          "paid"
        ) {
          setStatus("paid");
          return;
        }

        /*
         * Bank payments may not confirm
         * immediately.
         */
        if (
          data.payment_status ===
            "unpaid" ||
          data.payment_status ===
            "processing" ||
          data.payment_status ===
            "initiated"
        ) {
          setStatus("processing");
          return;
        }

        setStatus("processing");
      } catch (error) {
        console.error(error);

        if (!cancelled) {
          setStatus("error");
        }
      }
    };

    checkStatus();

    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <main className="min-h-[70vh] flex items-center justify-center px-4 py-20 bg-gradient-to-b from-blue-50/60 to-white">
      <div className="w-full max-w-xl rounded-3xl bg-white border border-slate-100 p-8 sm:p-12 text-center card-soft">
        {status === "loading" && (
          <>
            <Loader2 className="mx-auto h-12 w-12 text-blue-600 animate-spin" />

            <h1 className="mt-6 text-3xl font-display font-bold text-slate-900">
              Checking your donation…
            </h1>
          </>
        )}

        {status === "paid" && (
          <>
            <CheckCircle2 className="mx-auto h-14 w-14 text-blue-600" />

            <h1 className="mt-6 text-3xl font-display font-bold text-slate-900">
              Thank you!
            </h1>

            <p className="mt-4 text-slate-600 text-lg">
              Your donation was
              successfully received.
            </p>

            {donation?.amount && (
              <div className="mt-6 text-3xl font-bold text-slate-900">
                $
                {Number(
                  donation.amount
                ).toFixed(2)}
              </div>
            )}

            <Heart className="mx-auto mt-6 h-7 w-7 text-blue-600" />
          </>
        )}

        {status === "processing" && (
          <>
            <Loader2 className="mx-auto h-12 w-12 text-blue-600 animate-spin" />

            <h1 className="mt-6 text-3xl font-display font-bold text-slate-900">
              Thank you!
            </h1>

            <p className="mt-4 text-slate-600">
              Stripe received your
              payment. Some bank payments
              take additional time to
              confirm.
            </p>
          </>
        )}

        {status === "error" && (
          <>
            <AlertCircle className="mx-auto h-12 w-12 text-slate-500" />

            <h1 className="mt-6 text-3xl font-display font-bold text-slate-900">
              We couldn't verify the
              payment yet.
            </h1>

            <p className="mt-4 text-slate-600">
              Check your Stripe confirmation
              or contact us if you have any
              questions.
            </p>
          </>
        )}

        <Link to="/">
          <Button className="mt-8 rounded-full bg-blue-600 hover:bg-blue-700 px-8">
            Return home
          </Button>
        </Link>
      </div>
    </main>
  );
}